mapper.select:
SELECT mlr.*, CASE mlr.operation_type WHEN 'PICK' THEN '领料' WHEN 'RETURN' THEN '退料' ELSE mlr.operation_type END as operation_type_name, mld.material_name, mld.material_spec, coalesce(nullif(mlr.operator, ''), mlr.create_by) AS operator_name FROM mes_material_list_record mlr LEFT JOIN mes_material_list_detail mld ON mlr.material_list_detail_id = mld.id AND mlr.tenant_id = mld.tenant_id AND mlr.factory_code = mld.factory_code AND mlr.task_id = mld.task_id WHERE mlr.del_flag = '0' AND mlr.material_code = #{materialCode}
AND mlr.factory_code = #{factoryCode}
ORDER BY mlr.operation_time DESC, mlr.id DESC
